533	    if constexpr (Opt == OptId::Prodigy) {
534	        PrecomputeWorkspace pw{};
535	        pw.prodigy_partials = opt_reduce;            // [r slots | s slots]
536	        pw.prodigy_d        = opt_reduce + 2 * nCTA; // reduced-d broadcast slot
537	        // d_prev: persisted d_lr (slot 2 of prodigy_persist), or d0 at step 1.
538	        const float d_prev = (step == 1) ? st.d0 : st.prodigy_persist[2];
539	        st.d_factor = d_prev;   // phaseA reads st.d_factor as d_prev (prodigy.h)
540	        // Phase A: each CTA accumulates Σ d_prev²·<g,p0−p> / Σ d_prev²·|g| over its
541	        // claimed tensors → per-CTA (r,s) slots. Drains the task queue (the P3
542	        // re-drain below needs a queue reset, done at the barrier).
543	        prodigy_precompute_reduce_phaseA(ctx, params, st.param_init, grad,
544	                                         kDecSizes, kDecOffsets, d_prev, pw);
545	        bar.sync_reset(ctx.g_next_task);   // B2.6a: slots published; reset queue for P3
546	        // Owner block (CTA0 thread0): EMA decay + accumulate + d_coef + update_d,
547	        // byte-matching launch_multi_tensor_prodigy_fused_reduce_step.
548	        if (cta == 0 && threadIdx.x == 0) {
549	            float r_step = 0.0f, s_step = 0.0f;     // ascending-CTA owner-sum
550	            for (int c = 0; c < nCTA; ++c) {
551	                r_step += pw.prodigy_partials[c];
552	                s_step += pw.prodigy_partials[nCTA + c];
553	            }
554	            // Decay persisted scalars by beta3, then add this step's reduction.
555	            const float r_ema = st.beta3 * st.prodigy_persist[0] + r_step;
556	            const float s_ema = st.beta3 * st.prodigy_persist[1] + s_step;
557	            // d = max(d_prev, d_coef·r_ema/|s_ema|). prodigy_update_d does
558	            // max(d_prev, r/|s|) verbatim, so fold d_coef into the numerator copy
559	            // (persisted r_ema stays UNSCALED — returned/persisted, eager parity).
560	            const float d_new = algo::prodigy_update_d(d_prev, st.d_coef * r_ema, s_ema);
561	            st.prodigy_persist[0] = r_ema;          // persist UNSCALED EMA
562	            st.prodigy_persist[1] = s_ema;
563	            st.prodigy_persist[2] = d_new;          // persisted d_lr for next step
564	            pw.prodigy_d[0]       = d_new;          // broadcast to all CTAs
565	        }
